WITH enriched AS (SELECT id, order_date, status, channel, shipping_fee, FIRST_VALUE(discount) IGNORE NULLS OVER (PARTITION BY customer_id, channel ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_discount, AVG(discount) OVER (PARTITION BY channel ORDER BY amount, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS discount_avg_5_prior, RANK() OVER (PARTITION BY channel, status ORDER BY shipping_fee NULLS LAST) AS shipping_fee_rank, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY shipping_fee) AS shipping_fee_cume_dist FROM orders WHERE amount < 1190) SELECT id, order_date, status, channel, shipping_fee, first_known_discount, discount_avg_5_prior, shipping_fee_rank, shipping_fee_cume_dist FROM enriched ORDER BY channel DESC;
